# B01: two endpoint difference updates in a Fenwick, vs direct range updates.
def range_point(a,ops):
    n=len(a); bit=[0]*(n+1)
    def add(i,v):
        while i<=n: bit[i]+=v; i+=i&-i
    def query(i):
        s=0
        while i: s+=bit[i]; i-=i&-i
        return s
    for i,x in enumerate(a,1): add(i,x-(a[i-2] if i>1 else 0))
    ans=[]
    for op in ops:
        if op[0]==1:
            _,l,r,k=op; add(l,k); add(r+1,-k)
        else: ans.append(query(op[1]))
    return ans
