# B02: fixed window rolling sums vs exhaustive starts.
def fence(a,k):
    s=sum(a[:k]); best=s; j=0
    for i in range(k,len(a)):
        s+=a[i]-a[i-k]
        if s<best: best=s; j=i-k+1
    return j+1
