# B03: modular matrix exponentiation vs repeated multiplication.
MOD=10**9+7
def mul(a,b):
    n=len(a); c=[[0]*n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            for j in range(n): c[i][j]=(c[i][j]+a[i][k]*b[k][j])%MOD
    return c
def mpow(a,k):
    n=len(a); ans=[[int(i==j) for j in range(n)] for i in range(n)]; a=[[v%MOD for v in row] for row in a]
    while k:
        if k&1: ans=mul(ans,a)
        a=mul(a,a); k//=2
    return ans
