# B04: connected-component cache vs fresh reachability from every cell.
def components(grid):
    n=len(grid); lab=[[-1]*n for _ in range(n)]; sizes=[]
    for r in range(n):
        for c in range(n):
            if lab[r][c]>=0: continue
            k=len(sizes); lab[r][c]=k; q=[(r,c)]
            for x,y in q:
                for u,v in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=u<n and 0<=v<n and lab[u][v]<0 and grid[u][v]!=grid[x][y]: lab[u][v]=k; q.append((u,v))
            sizes.append(len(q))
    return [[sizes[lab[r][c]] for c in range(n)] for r in range(n)]
def reach(grid,r,c):
    n=len(grid); seen={(r,c)}; q=[(r,c)]
    for x,y in q:
        for u,v in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=u<n and 0<=v<n and (u,v) not in seen and grid[u][v]!=grid[x][y]: seen.add((u,v)); q.append((u,v))
    return len(seen)
