# B05: tree independent-set DP vs all vertex subsets.
def party(w,parent):
    n=len(w); children=[[] for _ in w]; root=0
    for i,p in enumerate(parent):
        if p<0: root=i
        else: children[p].append(i)
    def dfs(u):
        no=0; yes=w[u]
        for v in children[u]:
            a,b=dfs(v); no+=max(a,b); yes+=a
        return no,yes
    return max(dfs(root))
def party_brute(w,p):
    ans=0
    for mask in range(1<<len(w)):
        if any(parent>=0 and mask>>i&1 and mask>>parent&1 for i,parent in enumerate(p)): continue
        ans=max(ans,sum(x for i,x in enumerate(w) if mask>>i&1))
    return ans
