# B07: AC fail-reverse visit propagation vs exact substring membership.
def ac_count(patterns,text):
    nxt=[{}]; fail=[0]; weight=[0]
    for s in patterns:
        u=0
        for ch in s:
            if ch not in nxt[u]: nxt[u][ch]=len(nxt); nxt.append({}); fail.append(0); weight.append(0)
            u=nxt[u][ch]
        weight[u]+=1
    alphabet=sorted(set(''.join(patterns)+text))
    q=deque(nxt[0].values()); order=[]
    for ch in alphabet: nxt[0].setdefault(ch,0)
    while q:
        u=q.popleft(); order.append(u)
        for ch in alphabet:
            if ch in nxt[u]:
                v=nxt[u][ch]; fail[v]=nxt[fail[u]][ch]; q.append(v)
            else: nxt[u][ch]=nxt[fail[u]][ch]
    seen=[False]*len(nxt); u=0
    for ch in text:
        u=nxt[u][ch]; seen[u]=True
    for v in reversed(order): seen[fail[v]]|=seen[v]
    return sum(w for w,s in zip(weight,seen) if s)
