    patterns=[''.join(rng.choice('ab') for _ in range(rng.randint(1,6))) for _ in range(rng.randint(1,12))]; text=''.join(rng.choice('ab') for _ in range(rng.randint(1,15)))
    eq(ac_count(patterns,text),sum(s in text for s in patterns))
