# B08: augmenting paths vs every possible assignment on all graphs up to 3x3.
def kuhn(n,m,edges):
    adj=[[] for _ in range(n)]
    for u,v in edges: adj[u].append(v)
    match=[-1]*m
    def dfs(u,seen):
        for v in adj[u]:
            if v in seen: continue
            seen.add(v)
            if match[v]<0 or dfs(match[v],seen): match[v]=u; return True
        return False
    return sum(dfs(u,set()) for u in range(n))
def match_brute(n,m,edges):
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v)
    def go(u,used):
        if u==n: return 0
        return max([go(u+1,used)]+[1+go(u+1,used|{v}) for v in adj[u]-used])
    return go(0,set())
