# B09: ring interval DP vs recursion over every current adjacent merge.
def stone_dp(a):
    n=len(a); b=a*2; pre=[0]
    for v in b: pre.append(pre[-1]+v)
    lo=[[0]*(2*n) for _ in b]; hi=[[0]*(2*n) for _ in b]
    for length in range(2,n+1):
        for l in range(2*n-length+1):
            r=l+length-1; s=pre[r+1]-pre[l]
            lo[l][r]=min(lo[l][k]+lo[k+1][r]+s for k in range(l,r)); hi[l][r]=max(hi[l][k]+hi[k+1][r]+s for k in range(l,r))
    return min(lo[l][l+n-1] for l in range(n)),max(hi[l][l+n-1] for l in range(n))
@lru_cache(None)
def stone_brute(a):
    if len(a)==1: return 0,0
    outcomes=[]
    for k in range(len(a)):
        b=a[k:]+a[:k]; s=b[0]+b[1]; low,high=stone_brute((s,)+b[2:]); outcomes.append((s+low,s+high))
    return min(v[0] for v in outcomes),max(v[1] for v in outcomes)
