# B10: reverse greedy vs complete unit-edge shortest-path BFS on a safe bounded graph.
def buttons(n,m):
    steps=0
    while m>n:
        if m%2: m+=1
        else: m//=2
        steps+=1
    return steps+n-m
def buttons_bfs(n,m):
    bound=2*max(n,m)+2; q=deque([n]); dist={n:0}
    while q:
        x=q.popleft()
        if x==m: return dist[x]
        for y in (x*2,x-1):
            if 1<=y<=bound and y not in dist: dist[y]=dist[x]+1; q.append(y)
