# B11: exact counting DP vs enumeration of unique complete output permutations.
@lru_cache(None)
def stack_dp(p,s):
    if p==0 and s==0: return 1
    return (stack_dp(p-1,s+1) if p else 0)+(stack_dp(p,s-1) if s else 0)
def stack_outputs(n):
