# B17: explicit DSU construction followed by step-by-step edge simulation.
class DSU:
    def __init__(self,n): self.p=list(range(n)); self.c=n
    def find(self,x):
        while self.p[x]!=x: self.p[x]=self.p[self.p[x]]; x=self.p[x]
        return x
    def union(self,u,v):
        u=self.find(u); v=self.find(v)
        if u==v: return False
        self.p[v]=u; self.c-=1; return True

def reconnect(n,edges):
    d=DSU(n); redundant=[]
    for u,v in edges:
        if not d.union(u,v): redundant.append((u,v))
    roots=sorted({d.find(x) for x in range(n)}); eq(len(redundant),len(roots)-1)
    return [(u,v,roots[0],r) for (u,v),r in zip(redundant,roots[1:])]
def validate_reconnect(n,edges):
    initial=DSU(n)
    for u,v in edges: initial.union(u,v)
    ops=reconnect(n,edges); eq(len(ops),initial.c-1); current={tuple(sorted(e)) for e in edges}
    for u,v,x,y in ops:
        old=tuple(sorted((u,v))); new=tuple(sorted((x,y))); assert old in current; current.remove(old); assert x!=y and new not in current; current.add(new); eq(len(current),n-1)
    final=DSU(n)
    for u,v in current: final.union(u,v)
    eq(final.c,1)
    return ops
