# B18: lazy tree vs direct mutable array, plus exact weighted-difference overflow witness.
class LazyTree:
    def __init__(self,a):
        self.n=len(a); self.s=[0]*(4*self.n); self.z=[0]*(4*self.n)
        def build(p,l,r):
            if l==r: self.s[p]=a[l]; return
            m=(l+r)//2; build(p*2,l,m); build(p*2+1,m+1,r); self.s[p]=self.s[p*2]+self.s[p*2+1]
        build(1,0,self.n-1)
    def apply(self,p,l,r,k): self.s[p]+=k*(r-l+1); self.z[p]+=k
    def push(self,p,l,r):
        if l<r and self.z[p]:
            m=(l+r)//2; self.apply(p*2,l,m,self.z[p]); self.apply(p*2+1,m+1,r,self.z[p]); self.z[p]=0
    def add(self,ql,qr,k,p=1,l=0,r=None):
        if r is None: r=self.n-1
        if ql<=l and r<=qr: self.apply(p,l,r,k); return
        self.push(p,l,r); m=(l+r)//2
        if ql<=m: self.add(ql,qr,k,p*2,l,m)
